// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 _val) public {
        uint256 val = _val % (1 ether * 1000);

        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.MinSum() == val);
        } else {
            assertTrue(ok == false);
        }
    }
}
